در هر دو مسیر، caller همان Task را await کرد. اگر API callback لغو یا unregister دارد، آن مالکیت را هم در طول عمر عملیات مدیریت کن. TaskCompletionSource خودش کار خارجی را متوقف نمی‌کند.

ValueTask می‌تواند از IValueTaskSource و token نسخه استفاده کند. یک منبع ممکن است پس از پایان برای عملیات بعدی Reset شود. برای عملیات جاری یک بار await کن. اگر چند مشاهده لازم است، یک بار AsTask بگیر و همان Task را مشترک کن.
```csharp
using System.Threading.Tasks.Sources;

var source = new ReadSource();
ValueTask<int> waiting = source.Begin();
Console.WriteLine(waiting.IsCompleted);

Task<int> shared = waiting.AsTask();
source.Finish(8);
Console.WriteLine(await shared);
Console.WriteLine(await shared);

ValueTask<int> next = source.Begin();
source.Finish(5);
Console.WriteLine(await next);

sealed class ReadSource : IValueTaskSource<int>
{
    private ManualResetValueTaskSourceCore<int> core = new()
    {
        RunContinuationsAsynchronously = true
    };

    public ValueTask<int> Begin()
    {
        core.Reset();
        return new ValueTask<int>(this, core.Version);
    }

    public void Finish(int value) => core.SetResult(value);
    public int GetResult(short token) => core.GetResult(token);
    public ValueTaskSourceStatus GetStatus(short token) => core.GetStatus(token);

    public void OnCompleted(Action<object?> continuation, object? state,
        short token, ValueTaskSourceOnCompletedFlags flags) =>
        core.OnCompleted(continuation, state, token, flags);
}
```
