در Program.cs خروجی NumericLiteralExpression و System_Int32 را می‌بینی. اولی شکل node است. دومی نوعی است که compilation برای همان عبارت فهمیده است.

در پروژهٔ CompilerLab جلسهٔ قبل، FlagAnalyzer.cs را بساز. analyzer فقط node مربوط به == را بررسی می‌کند. سمت راست باید true و سمت چپ یک شناسه از نوع bool باشد.
```cs-snippet
using System.Collections.Immutable;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Diagnostics;

sealed class FlagAnalyzer : DiagnosticAnalyzer
{
    private static readonly DiagnosticDescriptor Rule = new("BOOL001",
        "Redundant comparison", "Use the boolean value directly", "Style",
        DiagnosticSeverity.Warning, isEnabledByDefault: true);

    public override ImmutableArray<DiagnosticDescriptor> SupportedDiagnostics =>
        ImmutableArray.Create(Rule);

    public override void Initialize(AnalysisContext context)
    {
        context.ConfigureGeneratedCodeAnalysis(GeneratedCodeAnalysisFlags.None);
        context.EnableConcurrentExecution();
        context.RegisterSyntaxNodeAction(ctx =>
        {
            var node = (BinaryExpressionSyntax)ctx.Node;
            if (node.Left is IdentifierNameSyntax &&
                node.Right.IsKind(SyntaxKind.TrueLiteralExpression) &&
                ctx.SemanticModel.GetTypeInfo(node.Left).Type?.SpecialType == SpecialType.System_Boolean)
                ctx.ReportDiagnostic(Diagnostic.Create(Rule, node.GetLocation()));
        }, SyntaxKind.EqualsExpression);
    }
}
```
Program.cs را عوض کن و dotnet run بزن.
