FlagAnalyzer.cs و Program.cs جلسهٔ قبل را نگه دار. FlagFix.cs را به پروژه اضافه کن. پیشنهاد فقط برای diagnostic با شناسهٔ BOOL001 ارائه می‌شود. ReplaceNode عبارت مقایسه را با خود عبارت سمت چپ جایگزین می‌کند.
```cs-snippet
using System.Collections.Immutable;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CodeActions;
using Microsoft.CodeAnalysis.CodeFixes;
using Microsoft.CodeAnalysis.CSharp.Syntax;

sealed class FlagFix : CodeFixProvider
{
    public override ImmutableArray<string> FixableDiagnosticIds => ImmutableArray.Create("BOOL001");

    public override async Task RegisterCodeFixesAsync(CodeFixContext context)
    {
        var root = await context.Document.GetSyntaxRootAsync(context.CancellationToken);
        if (root?.FindNode(context.Span) is not BinaryExpressionSyntax node)
            return;

        context.RegisterCodeFix(CodeAction.Create("Use the boolean value",
            _ => Task.FromResult(context.Document.WithSyntaxRoot(
                root.ReplaceNode(node, node.Left.WithTriviaFrom(node)))),
            "UseBooleanValue"), context.Diagnostics);
    }
}
```
قطعهٔ بعد را پس از Console.WriteLine(diagnostic.Id) در Program.cs اضافه کن. usingهای ابتدای فایل را نگه دار و dotnet run را اجرا کن.
