[{"Index":1,"Value":0},{"Index":3,"Value":3},{"Index":9,"Value":4}]
```

کنار Worker پوشهٔ Tests بساز و از Tests.csproj فصل R122 استفاده کن. ProjectReference را به ../Worker/Worker.csproj تغییر بده. این کد را در Tests/WorkerTests.cs قرار بده. partial یعنی بخشی از همین کلاس را در فایل بعدی می‌نویسیم. هر آزمون یک نمونه و پوشهٔ مستقل دارد و Dispose آن پوشه را جمع می‌کند.
```cs-snippet
using System.Text.Json;
using Xunit;

public sealed partial class WorkerTests : IDisposable
{
    private readonly DirectoryInfo _directory = Directory.CreateTempSubdirectory("worker-test-");
    private string Input => Path.Combine(_directory.FullName, "input.json");
    private string Output => Path.Combine(_directory.FullName, "output.json");

    [Fact]
    public async Task SortsByIndexAndAppliesPolicy()
    {
        await File.WriteAllTextAsync(Input, """[{"Index":2,"Value":4},{"Index":0,"Value":2}]""");
        Assert.Equal(4L, await DataJob.RunAsync(Input, Output, new AboveTwo(), CancellationToken.None));
        ReportRow[] actual = JsonSerializer.Deserialize<ReportRow[]>(await File.ReadAllTextAsync(Output))!;
        Assert.Equal(new[] { new ReportRow(0, 0), new ReportRow(2, 4) }, actual);
    }

    [Theory]
    [InlineData("[broken", typeof(JsonException))]
    [InlineData("""[{"Index":0}]""", typeof(JsonException))]
    [InlineData("""[{"Index":0,"Value":-1}]""", typeof(InvalidDataException))]
    [InlineData("""[{"Index":1000,"Value":1}]""", typeof(InvalidDataException))]
    [InlineData("""[{"Index":0,"Value":2},{"Index":0,"Value":4}]""", typeof(InvalidDataException))]
    public async Task RejectsInvalidInputAndKeepsPreviousFile(string json, Type error)
    {
        await File.WriteAllTextAsync(Input, json);
        await File.WriteAllTextAsync(Output, "previous");
        await Assert.ThrowsAsync(error,
            () => DataJob.RunAsync(Input, Output, new AboveTwo(), CancellationToken.None));
        Assert.Equal("previous", await File.ReadAllTextAsync(Output));
    }

    [Fact]
    public async Task RejectsBytesBeyondLimit()
    {
        await File.WriteAllTextAsync(Input, new string(' ', InputFile.MaxBytes) + "[]");
        await Assert.ThrowsAsync<InvalidDataException>(
            () => DataJob.RunAsync(Input, Output, new AboveTwo(), CancellationToken.None));
        Assert.False(File.Exists(Output));
    }

    public void Dispose() => _directory.Delete(recursive: true);
}
```
dotnet test Tests/Tests.csproj -c Release را اجرا کن. این مرحله ۷ مورد را بررسی می‌کند. در مسیر موفق، هم جمع و هم ردیف‌های مرتب را مقایسه کن. در مسیر نامعتبر، هم نوع خطا و هم متن فایل قبلی را بسنج. در آزمون سقف، ورودی پیش از ساخت فایل خروجی رد می‌شود.

این بخش را در Tests/WorkerFailureTests.cs کنار WorkerTests.cs قرار بده. هر دو فایل بخش‌های یک کلاس partial هستند. Input، Output و پاک‌سازی پوشه از فایل قبلی می‌آیند. BrokenPolicy هنگام پردازش خطا ایجاد می‌کند و CancelPolicy درخواست لغو می‌دهد.
```cs-snippet
using System.Text.Json;
using Xunit;

public sealed partial class WorkerTests
{
    [Fact]
    public async Task WorkerFailureKeepsPreviousFile()
    {
        var jobs = Enumerable.Range(0, 8).Select(index => new Job(index, 5));
        await File.WriteAllTextAsync(Input, JsonSerializer.Serialize(jobs));
        await File.WriteAllTextAsync(Output, "previous");
        await Assert.ThrowsAsync<InvalidOperationException>(() =>
            DataJob.RunAsync(Input, Output, new BrokenPolicy(), CancellationToken.None)
                .WaitAsync(TimeSpan.FromSeconds(10)));
        Assert.Equal("previous", await File.ReadAllTextAsync(Output));
        Assert.Empty(_directory.EnumerateFiles("*.tmp"));
    }

    [Fact]
    public async Task CancellationDuringWorkKeepsPreviousFile()
    {
        await File.WriteAllTextAsync(Input, """[{"Index":0,"Value":5}]""");
        await File.WriteAllTextAsync(Output, "previous");
        using var stop = new CancellationTokenSource();
        await Assert.ThrowsAnyAsync<OperationCanceledException>(() =>
            DataJob.RunAsync(Input, Output, new CancelPolicy(stop), stop.Token)
                .WaitAsync(TimeSpan.FromSeconds(10)));
        Assert.Equal("previous", await File.ReadAllTextAsync(Output));
    }

    [Fact]
    public void CancellationBeforeCommitKeepsPreviousFile()
    {
        string staged = Path.Combine(_directory.FullName, "output.tmp");
        File.WriteAllText(staged, "next");
        File.WriteAllText(Output, "previous");

        Assert.Throws<OperationCanceledException>(() =>
            OutputFile.Commit(staged, Output, new CancellationToken(canceled: true)));
        Assert.Equal("previous", File.ReadAllText(Output));
        Assert.Equal("next", File.ReadAllText(staged));
    }

    private sealed class BrokenPolicy : ITransform
    {
        public int Apply(int value) => throw new InvalidOperationException("injected");
    }

    private sealed class CancelPolicy(CancellationTokenSource stop) : ITransform
    {
        public int Apply(int value)
        {
            stop.Cancel();
            return value;
        }
    }
}
```
دوباره dotnet test Tests/Tests.csproj -c Release را اجرا کن. با سه آزمون تازه، ۱۰ مورد باید بگذرند. در دو اجرای کامل، مقصد قبلی پس از خطا یا لغو بررسی می‌شود. در آزمون مستقیم Commit، فایل موقت از قبل آماده است و باقی می‌ماند. پاک کردن موقت در اجرای کامل مسئولیت WriteAsync است.

S01.Text:
کامپایلر C# سورس را بررسی و معمولاً IL به‌همراه metadata تولید می‌کند. IL دستورهای میانی است. metadata توصیف نوع‌ها، اعضا و ارجاع‌های اسمبلی است. manifest بخش شناسنامهٔ اسمبلی است و نام، نسخه و وابستگی‌های اعلام‌شده را نگه می‌دارد. اسمبلی مدیریت‌شده معمولاً فایل dll است. برنامهٔ اجرایی .NET می‌تواند یک فایل راه‌انداز هم در کنار آن داشته باشد. صرف پسوند dll برای تشخیص مدیریت‌شده بودن کافی نیست.
```text
Program.cs → کامپایلر C# → اسمبلی دارای IL و metadata
اسمبلی → بارگذار CLR → JIT برای متد مورد نیاز → کد ماشین
```
این نمونه نشان می‌دهد metadata در برنامه قابل خواندن است. typeof به نوع Score دسترسی می‌دهد و GetProperty نام و نوع property را پیدا می‌کند.
```csharp
var type = typeof(Score);
var property = type.GetProperty(nameof(Score.Points))!;
Console.WriteLine(type.Name);
Console.WriteLine(property.PropertyType.Name);

sealed class Score
{
    public int Points { get; set; }
}
```
```output
Score
Int32
```
CLR محیط اجرای کد مدیریت‌شده است. هنگام اجرای معمول JIT، runtime متد را در زمان نیاز به دستورهای مناسب پردازنده تبدیل می‌کند. کامپایلر C#، بارگذار و JIT نقش‌های جدا دارند. جزئیات آماده‌سازی و بهینه‌سازی می‌توانند با شیوهٔ انتشار فرق کنند.

S02.Text:
در int steps = 3 نام متغیر steps است، int نوع و 3 مقدار آغازین است. int برای عدد صحیح در محدودهٔ ۳۲ بیت کاربرد دارد. long بازهٔ بزرگ‌تری دارد. decimal برای محاسبهٔ ده‌دهی مثل قیمت کاربرد دارد. bool فقط true یا false است. char یک واحد UTF-16 می‌گیرد و با تک‌نقل‌قول نوشته می‌شود. string دنباله‌ای از واحدهای UTF-16 است و با دونقل‌قول نوشته می‌شود.
```csharp
int steps = 3;
long worldTicks = 5_000_000_000L;
decimal price = 12.5m;
bool open = steps > 0;
char key = 'A';
string name = "Gate";
steps = steps + 2;

Console.WriteLine(steps);
Console.WriteLine(worldTicks > int.MaxValue);
Console.WriteLine(price > 10m);
Console.WriteLine(open);
Console.WriteLine(key + " " + name);
```
```output
5
True
True
True
A Gate
```
پسوند m نوع literal را decimal می‌کند. var از مقدار سمت راست نوع ثابت را استنباط می‌کند. بعداً هم باید به همان نوع مقدار سازگار بدهی. برای موقعیت یا سرعت تقریبی، نوع ممیز شناور double معمولاً مناسب است. برای شمارش، نوع صحیح را در بازهٔ مورد نیاز انتخاب کن.

انتساب مقدار int، خود مقدار را در متغیر مقصد کپی می‌کند. تغییر نسخهٔ دوم به نسخهٔ اول سرایت نمی‌کند.
```csharp
int speed = 4;
int previous = speed;
speed = 7;
Console.WriteLine(previous);
```
```output
4
```
آرایه شیء است و متغیر آرایه مرجع آن را نگه می‌دارد. کپی مرجع دو راه برای رسیدن به همان آرایه می‌سازد. خانهٔ اول با [0] خوانده می‌شود. انتساب new int[] مرجع یک متغیر را عوض می‌کند.
```csharp
int[] points = [6, 9];
int[] same = points;
same[0] = 10;
Console.WriteLine(points[0]);
same = [15];
Console.WriteLine(points[0]);
Console.WriteLine(same[0]);
```
```output
10
10
15
```
| گام | points[0] | same[0] |
| --- | --- | --- |
| بعد از کپی مرجع | 6 | 6 |
| بعد از تغییر عضو | 10 | 10 |
| بعد از آرایهٔ تازه | 10 | 15 |
برای آرایه‌ای از int می‌توان ToArray یا Clone را برای ساخت آرایهٔ مستقل به‌کار برد. اگر خود عضوها مرجعی باشند، استقلال دادهٔ داخلی به نوع کپی عضو هم بستگی دارد.

string یک نوع مرجعی است و متن همان شیء بعد از ساخت عوض نمی‌شود. عملیات + متن تازه به دست می‌دهد و انتساب می‌تواند متغیر را به نتیجهٔ تازه وصل کند.
```csharp
string name = "Red";
string label = name;
name += " Team";
Console.WriteLine(label);
Console.WriteLine(name);
```
```output
Red
Red Team
```
متد در این مثال یک ورودی به‌نام box می‌گیرد. پیشوند static و پارامتر را در S05 بیشتر تمرین می‌کنی. هنگام فراخوانی، مقدار مرجع در متغیر پارامتر کپی می‌شود. تغییر عضو از هر دو مسیر دیده می‌شود و انتساب به خود پارامتر فقط همان متغیر محلی را عوض می‌کند.
```csharp
var outer = new Box { Count = 4 };
Change(outer);
Console.WriteLine(outer.Count);

static void Change(Box box)
{
    box.Count = 7;
    box = new Box { Count = 10 };
    Console.WriteLine(box.Count);
}

sealed class Box
{
    public int Count { get; set; }
}
```
```output
10
7
```
برای دادن شیء تازه به فراخواننده می‌توان آن را return کرد و در متغیر مقصد قرار داد. راه دیگر پارامتر ref است که در S05 می‌بینی.

default برای int صفر، برای bool مقدار false و برای مرجع null است. فیلدها و خانه‌های آرایه ابتدا مقدار پیش‌فرض می‌گیرند. متغیر محلی باید قبل از خواندن در همهٔ مسیرها مقداردهی شده باشد. می‌توان با default آن را صریح مقداردهی کرد.
```csharp
int count = default;
string? title = default;
var board = new Board();
var visits = new int[2];
Console.WriteLine(count);
Console.WriteLine(title is null);
Console.WriteLine(board.Score);
Console.WriteLine(visits[1]);

sealed class Board
{
    public int Score;
}
```
```output
0
True
0
0
```
```csharp-error CS0165
int count;
Console.WriteLine(count);
```
Score با اینکه int و مقداری است، درون شیء Board نگه‌داری می‌شود. خانهٔ int درون آرایه هم همین‌طور. runtime ممکن است یک مقدار محلی را در رجیستر یا جای دیگری قرار دهد. رفتار انتساب و کپی از نوع معلوم است و برای فهم آن نیازی به حدس دربارهٔ stack و heap نیست.

S03.Text:
تبدیل int به long بدون cast ممکن است، چون long همهٔ مقدارهای int را می‌پذیرد. برای تبدیل decimal به int از cast صریح استفاده کن. این تبدیل بخش اعشاری را به سمت صفر حذف می‌کند. اگر نتیجه از بازهٔ int بیرون باشد، تبدیل decimal به int خطا می‌دهد.
```csharp
int total = 9;
long wide = total;
Console.WriteLine(wide);
Console.WriteLine(total / 2);
Console.WriteLine(total % 2);
Console.WriteLine(total / 2.0);
Console.WriteLine((int)(-3.9m));
```
```output
9
4
1
4.5
-3
```
تقسیم دو int صحیح است. اگر بعد از تقسیم cast کنی، اعشار از دست رفته است. یکی از طرف‌ها را پیش از تقسیم به نوع اعشاری تبدیل کن. عملگر % باقیمانده را می‌دهد. == و > نتیجهٔ bool دارند. && پس از false سمت چپ و || پس از true سمت چپ، سمت راست را اجرا نمی‌کنند. ! مقدار منطقی را برعکس می‌کند.
```csharp
string? code = null;
Console.WriteLine(code is not null && code.Length > 2);
Console.WriteLine(9 % 2 != 0 || code!.Length == 3);
```
```output
False
True
```
در خط دوم سمت راست برای مقدار نمونه ارزیابی نمی‌شود. ! پس از code در آن خط هشدار nullable را خاموش می‌کند و بررسی زمان اجرا اضافه نمی‌کند. برای دادهٔ متغیر، guard روشن مثل code is not null بگذار.

وقتی int را به object می‌دهی، runtime یک نمونهٔ boxed با کپی مقدار می‌سازد. باز کردن جعبه باید با همان نوع مقدار انجام شود. ابتدا به int باز کن و بعد در صورت نیاز به long تبدیل کن. بررسی is int هم نوع را می‌سنجد و هم مقدار را در متغیر تازه می‌گذارد.
```csharp
object boxed = 13;
Console.WriteLine((long)(int)boxed);
try
{
    Console.WriteLine((long)boxed);
}
catch (InvalidCastException)
{
    Console.WriteLine("wrong type");
}

object? text = "gate";
Console.WriteLine(text is int);
Console.WriteLine(text as string);
Console.WriteLine((boxed as string) is null);
Console.WriteLine((boxed as int?) == 13);
```
```output
13
wrong type
False
gate
True
True
```
as در ناسازگاری به null می‌رسد و برای نوع مرجعی یا nullable کاربرد دارد. is int روی null برابر false است. یک int? با مقدار، هنگام boxing همان int را می‌بندد و بدون مقدار به مرجع null تبدیل می‌شود. رشتهٔ "13" و عدد boxed مقدار هم‌نوع نیستند. تبدیل متن به عدد به parse جدا نیاز دارد.

وقتی محاسبهٔ int از بازه خارج می‌شود، unchecked بیت‌های باقی‌مانده را نگه می‌دارد. checked در زمان اجرا OverflowException می‌دهد. برای ثابت زمان کامپایل، عبارت بیرون از بازه می‌تواند خطای کامپایل باشد.
```csharp
int maximum = int.MaxValue;
Console.WriteLine(unchecked(maximum + 1));
try
{
    Console.WriteLine(checked(maximum + 1));
}
catch (OverflowException)
{
    Console.WriteLine("overflow");
}

static int AddOne(int value) => unchecked(value + 1);
Console.WriteLine(checked(AddOne(maximum)));

decimal big = decimal.MaxValue;
try
{
    Console.WriteLine(unchecked(big + 1m));
}
catch (OverflowException)
{
    Console.WriteLine("decimal overflow");
}
```
```output
-2147483648
overflow
-2147483648
decimal overflow
```
```csharp-error CS0220
const int TooBig = int.MaxValue + 1;
Console.WriteLine(TooBig);
```
checked بر عبارت‌هایی اثر می‌گذارد که از نظر نوشتاری داخل همان محدوده‌اند. AddOne محاسبهٔ خودش را انجام می‌دهد. برای بررسی آن، checked را داخل بدنهٔ آن بگذار یا سیاست ساخت را مشخص کن. عملگرهای decimal برای سرریز رفتار مستقل دارند و حتی داخل unchecked خطا می‌دهند.

این مثال دو نکته از فصل‌های بعد را آماده می‌کند. if بلوک شرطی را اجرا می‌کند و out به متد اجازه می‌دهد در متغیر خروجی مقدار بگذارد. در الگوی Try هم در موفقیت و هم در شکست به out مقدار بده. متد زیر پورت را فقط وقتی می‌پذیرد که نوع واقعی int و مقدار در بازه باشد.
```csharp
static bool TryReadPort(object? value, out int port)
{
    if (value is int number && number is >= 1 and <= 65535)
    {
        port = number;
        return true;
    }

    port = 0;
    return false;
}

Console.WriteLine(TryReadPort(80, out int valid) + " " + valid);
Console.WriteLine(TryReadPort("80", out int invalid) + " " + invalid);
```
```output
True 80
False 0
```
ارزیابی سمت راست && فقط پس از موفقیت is انجام می‌شود. در کارگاه بعدی قرارداد بازه فرق دارد. اول رفتار قبول و رد خود تمرین را بخوان و نمونهٔ موفق و ناموفق را دنبال کن.

S04.Text:
if بدنه را وقتی شرط true است اجرا می‌کند. else if پس از رد شرط قبلی بررسی می‌شود. else آخرین حالت را می‌گیرد. می‌توان اول ورودی نامعتبر را با guard رد کرد و بدنهٔ اصلی را با فرض ورودی معتبر ادامه داد.
```csharp
static string CheckEntry(int age, int tickets)
{
    if (age < 0 || tickets <= 0)
        return "invalid";

    if (age < 12)
        return "child";
    else
        return "standard";
}

Console.WriteLine(CheckEntry(10, 1));
Console.WriteLine(CheckEntry(20, 1));
Console.WriteLine(CheckEntry(20, 0));
```
```output
child
standard
invalid
```
return از متد خارج می‌شود. شرط invalid در مثال با || ساخته شده چون نامعتبر بودن هر کدام کافی است. اگر صفر در یکی از ورودی‌ها مجاز است، برای همان ورودی از < 0 استفاده کن و صفر را جداگانه تست کن.

switch statement در هر case یک بدنه دارد. با break از switch خارج می‌شود یا با return متد تمام می‌شود. switch expression از اولین الگوی منطبق یک مقدار می‌سازد. _ حالت باقیمانده را می‌گیرد. نوع دقیق، null، مقایسهٔ بازه و ویژگی طول را می‌توان در الگو دید.
```csharp
static string Describe(object? value) => value switch
{
    null => "missing",
    int count when count > 3 => "many",
    int and > 0 => "some",
    string { Length: > 0 } => "text",
    _ => "other"
};

Console.WriteLine(Describe(5));
Console.WriteLine(Describe(2));
Console.WriteLine(Describe(""));
Console.WriteLine(Describe(null));

switch (Describe("map"))
{
    case "text":
        Console.WriteLine("read");
        break;
    default:
        Console.WriteLine("skip");
        break;
}
```
```output
many
some
other
missing
read
```
when بعد از انطباق الگوی همان شاخه بررسی می‌شود. الگوی خاص‌تر را بالاتر بگذار. "other" هم عدد صفر و هم رشتهٔ خالی را می‌گیرد.

for مناسب وقتی است که اندیس یا تعداد دور را می‌دانی. while پیش از هر دور شرط را بررسی می‌کند. do/while پس از اولین دور بررسی می‌کند. foreach مقدارها را یکی‌یکی می‌گیرد و معمولاً برای پیمایش کل آرایه خواناتر است.
```csharp
int[] points = [4, 7, 9];
for (int i = 0; i < points.Length; i++)
    Console.WriteLine(i + "=" + points[i]);

int left = 2;
while (left > 0)
    left--;
Console.WriteLine(left);

bool repeat = false;
do
{
    Console.WriteLine("once");
}
while (repeat);

int sum = 0;
foreach (int point in points)
    sum += point;
Console.WriteLine(sum);
```
```output
0=4
1=7
2=9
0
once
20
```
Length تعداد خانه‌ها است. اندیس 0 تا Length - 1 معتبر است. برای آرایهٔ خالی، for با i < Length و foreach بدون دور تمام می‌شوند. در while، متغیر کنترل باید در مسیر مناسب تغییر کند تا شرط بتواند false شود.

break نزدیک‌ترین حلقه را تمام می‌کند. continue باقی همان دور را رد می‌کند و در for به بخش تغییر شمارنده می‌رود. return همهٔ متد را تمام می‌کند. ناوردا جمله‌ای است که در شروع هر دور برقرار می‌ماند. در SumEvenUntilStop، قبل از هر دور sum جمع عددهای زوجِ پردازش‌شدهٔ پیش از اولین مقدار منفی است.
```csharp
static int SumEvenUntilStop(int[] values)
{
    int sum = 0;
    foreach (int value in values)
    {
        if (value < 0)
            break;
        if (value % 2 != 0)
            continue;

        sum += value;
    }

    return sum;
}

Console.WriteLine(SumEvenUntilStop([2, 3, 4, -1, 8]));
Console.WriteLine(SumEvenUntilStop([]));
```
```output
6
0
```
ابتدا جمع 0 است. 2 جمع را 2 می‌کند، 3 بدون تغییر رد می‌شود، 4 جمع را 6 می‌کند و منفی حلقه را می‌بندد. 8 دیگر خوانده نمی‌شود. برای کارگاه شمارش، یک شمارندهٔ صفر و یک شرط ساده در foreach بساز. در هر دور، تعداد مقدارهای پذیرفته‌شدهٔ قبلی را نگه دار.

S05.Text:
در static int AddFee(int value)، نام متد AddFee، نوع نتیجه int و نام پارامتر value است. هنگام فراخوانی AddFee(price)، price آرگومان است. متد با return مقدار را می‌دهد. void برای متدی است که نتیجه‌ای برای انتساب ندارد. پارامتر عادی نسخه‌ای از مقدار آرگومان می‌گیرد.
```csharp
static int AddFee(int value)
{
    value += 2;
    return value;
}

static void RaiseFirst(int[] values)
{
    values[0] += 2;
    values = [100];
}

int price = 5;
int total = AddFee(price);
Console.WriteLine(price);
Console.WriteLine(total);

int[] points = [5];
RaiseFirst(points);
Console.WriteLine(points[0]);
```
```output
5
7
7
```
برای int، خود عدد کپی شد. برای آرایه، مقدار مرجع کپی شد و هر دو متغیر ابتدا به یک آرایه رسیدند. تغییر عضو دیده شد. انتساب آرایهٔ تازه به پارامتر روی متغیر بیرونی اثر نداشت. اگر هدف دادن مقدار تازه است، الگوی ساده return و انتساب در فراخواننده است.

ref اجازه می‌دهد متد همان متغیر مقداردهی‌شدهٔ فراخواننده را بخواند و عوض کند. out برای خروجی است. فراخواننده می‌تواند متغیر تازه معرفی کند. متد باید در تمام مسیرهای بازگشت عادی آن را مقداردهی کند. in امکان خواندن از مسیر فقط‌خواندنی را می‌دهد. فراخوانی با in صریح، متغیر آماده می‌خواهد.
```csharp
int score = 2;
Increase(ref score);
ReadStart(out int start);
Console.WriteLine(score);
Console.WriteLine(start);
Console.WriteLine(Double(in score));

int[] cells = [3];
Mark(in cells);
Console.WriteLine(cells[0]);

static void Increase(ref int value) => value++;
static void ReadStart(out int value) => value = 10;
static int Double(in int value) => value * 2;
static void Mark(in int[] items) => items[0] = 8;
```
```output
3
10
6
8
```
در Mark، انتساب یک آرایهٔ تازه به items مجاز نیست. تغییر خانهٔ خود آرایه مجاز است. فقط‌خواندنی بودن مسیر پارامتر لزوماً شیء اشاره‌شده را immutable نمی‌کند.
```csharp-error CS8331
int current = 1;
Change(in current);

static void Change(in int value)
{
    value = 3;
}
```
برای نوع‌های کوچک، پارامتر معمولی نقطهٔ شروع خواناست. وقتی لازم است خود متغیر تغییر کند یا قراردادی مشخص به خروجی جدا نیاز دارد، ref یا out را صریح به‌کار ببر.

برای الگوی Try معمولاً false همراه یک مقدار خروجی قابل پیش‌بینی است. پس از موفقیت از خروجی استفاده کن. این نمونه تعداد رزرو را می‌گیرد. مقدار کمتر از 1 و بیشتر از available را رد می‌کند.
```csharp
static bool TryReserve(int available, int requested, out int remaining)
{
    if (requested <= 0 || requested > available)
    {
        remaining = 0;
        return false;
    }

    remaining = available - requested;
    return true;
}

bool success = TryReserve(4, 2, out int first);
Console.WriteLine(success + " " + first);
bool zero = TryReserve(4, 0, out int second);
Console.WriteLine(zero + " " + second);
bool all = TryReserve(4, 4, out int last);
Console.WriteLine(all + " " + last);
```
```output
True 2
False 0
True 0
```
دو مسیر خروجی صفر داریم و bool آن‌ها را از هم جدا می‌کند. int.TryParse نیز همین ایده را برای متن عددی دارد. در کارگاه قیمت و تعداد، صفرِ مجاز قیمت را از صفرِ نامعتبر تعداد جدا کن. قبل از چاپ یا خواندن متغیرها، تعریف و فراخوانی لازم را انجام بده.

پارامتر params در انتهای فهرست می‌آید و پذیرش صفر یا چند آرگومان هم‌نوع را ساده می‌کند. شکل کلاسیک آرایه است. در C# 13 شکل‌هایی مانند ReadOnlySpan<T> هم مجازند. نوع نوشته‌شده در تعریف مشخص می‌کند بدنه چه چیزی دریافت می‌کند.
```csharp
static int AddAll(params int[] items) => items.Sum();

static int AddSpan(params ReadOnlySpan<int> items)
{
    int sum = 0;
    foreach (int value in items)
        sum += value;
    return sum;
}

Console.WriteLine(AddAll());
Console.WriteLine(AddAll(2, 3, 4));
Console.WriteLine(AddAll(new[] { 5, 6 }));
Console.WriteLine(AddSpan(7, 8));
```
